INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (1, 'Unusually slow performance or unusually active CPU’s? CPU cycles up and cycles down for no apparent reason? Does Network or ICS network traffic appear unusually high or busy between network layers or devices?', 'It seems that this anomaly might be related to:', 'Increased internet traffic', 'TECHNIQUE T875: CHANGE PROGRAM STATE – IMPAIR PROCESS CONTROL; TECHNIQUE T875: CHANGE PROGRAM STATE –; TECHNIQUE T868: DETECT OPERATING MODE; TECHNIQUE T858: UTILIZE/CHANGE OPERATING MODE; TECHNIQUE T836: MODIFY PARAMETER; TECHNIQUE T843: PROGRAM DOWNLOAD', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (2, 'Configuration changes to software made without user or system admin action? Configuration files changed without user or system admin action?', 'It seems that this anomaly might be related to:', 'Application logs indicating programs are being uploaded to other devices', 'TECHNIQUE T845: PROGRAM UPLOAD', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (3, 'Does Network or ICS network traffic appear unusually high or busy between network layers or devices? Is there any ICS process network traffic that appears unusually busy, either between devices, or across the ICS boundaries? <yes / no> ', 'It seems that this anomaly might be related to:', 'An increase of packet traffic', 'TECHNIQUE T855: UNAUTHORIZED COMMAND MESSAGE; TECHNIQUE T806: BRUTE FORCE I/O; TECHNIQUE T804: BLOCK REPORTING MESSAGE
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (4, 'Has ICS equipment both controllers and field devices been rebooting and restarting randomly out of the normal baseline?', 'It seems that this anomaly might be related to:', 'Device restarts and shutdowns recorded as events', 'TECHNIQUE T816: DEVICE RESTART/SHUTDOWN', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (5, 'Has ICS system command and control systems reported any nusual activitiy such as reboots and restarts to the ICS processes? ', 'It seems that this anomaly might be related to:', 'Alarms for shut down or restarted devices', 'TECHNIQUE T816: DEVICE RESTART/SHUTDOWN', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (6, 'Have any networked devices stopped communicating with other devices, servers, workstations, or SCADA equipment?', 'It seems that this anomaly might be related to:', 'Blocking of command messages', 'TECHNIQUE T855: UNAUTHORIZED COMMAND MESSAGE
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (7, 'Is there any new process has been implemented that are abnormal or anomalous? Are there any old processes that were removed that keep reappearing? ', 'It seems that this anomaly might be related to:', 'Unnecessary connections to the data historian or to devices', 'TECHNIQUE T806: BRUTE FORCE I/O', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (8, 'Devices generally have a single MAC and IP address if there are unknown MAC or IP address have any of the ICS devices failed and been replaced with new hardware? (If there have not been any recorded replacements this can identify possible MAC cloning and ', 'It seems that this anomaly might be related to:', 'Unfamiliar IP addresses noted in NetFlow log', 'TECHNIQUE T806: BRUTE FORCE I/O', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (9, 'Do you see inbound or outbound traffic between ICS network and any other network, including the Internet? Have you checked for any queries to multiple sites via IP not DNS? Are there any anomalous inbound or outbound telnet, FTP, TFTP, HTTP, HTTPS to or f', 'It seems that this anomaly might be related to:', 'Unfamiliar IP addresses noted in NetFlow logs', 'TECHNIQUE T855: UNAUTHORIZED COMMAND MESSAGE; TECHNIQUE T843: PROGRAM DOWNLOAD
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (10, 'Have any of the normal ICS process been altered? Is there any new process has been implemented that are abnormal or anomalous? Are there any old processes that were removed that keep reappearing? Have there been changes to the controller logic within the ', 'It seems that this anomaly might be related to:', 'Device operating mode change', 'TECHNIQUE T843: PROGRAM DOWNLOAD', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (11, 'Have logs been reviewed for anomalies against baseline software, configurations, authorized connections, and user accounts?', 'It seems that this anomaly might be related to:', 'Software being installed', 'TECHNIQUE T843: PROGRAM DOWNLOAD', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (12, 'Do you see inbound or outbound traffic between ICS network and any other network, including the Internet? ', 'It seems that this anomaly might be related to:', 'Increased internet traffic from potentially malicious IP addresses', 'TECHNIQUE T846: REMOTE SYSTEM DISCOVERY', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (13, 'Is there any ICS process network traffic that appears unusually busy, either between devices, or across the ICS boundaries? ', 'It seems that this anomaly might be related to:', 'Increased DMZ traffic between information technology (IT) and OT networks', 'TECHNIQUE T875: CHANGE PROGRAM STATE – IMPAIR PROCESS CONTROL; TECHNIQUE T875: CHANGE PROGRAM STATE –; TECHNIQUE T868: DETECT OPERATING MODE; TECHNIQUE T858: UTILIZE/CHANGE OPERATING MODE;  TECHNIQUE T855: UNAUTHORIZED COMMAND MESSAGE
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (14, 'Is there anomalous batch process executing outside of normal control traffic? Are there control services that run normally that are suddenly stopping starting or not running at all? ', 'It seems that this anomaly might be related to:', 'Event logs showing devices performing unexpected functions', 'TECHNIQUE T855: UNAUTHORIZED COMMAND MESSAGE
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (15, 'Were there any inbound or outbound traffic from unknown IP Addresses? Was there any unrecognized protocols like FTP, TFTP, HTTP, HTTPS, from unknown IP’s?', 'It seems that this anomaly might be related to:', 'Unfamiliar IP addresses', 'TECHNIQUE T859: VALID ACCOUNTS', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (16, 'Is there unusual user activity such as users logging when they are not supposed to, or logging into equipment they are not authorized to?', 'It seems that this anomaly might be related to:', 'Unexpected login sessions', 'TECHNIQUE T859: VALID ACCOUNTS', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (17, 'When reviewing system log files (such as Windows event log, syslog’s, or log files associated with applications) specifically looking at user accounts when compared to the normal or authorized list are there any unrecognized users? ', 'It seems that this anomaly might be related to:', 'New accounts being created (seen in authentication logs)', 'TECHNIQUE T859: VALID ACCOUNTS', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (18, 'Have there been any visible attemps from user logs to access restricted areas of the nework?', 'It seems that this anomaly might be related to:', 'Restricted areas of the network being accessed', 'TECHNIQUE T859: VALID ACCOUNTS', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (19, 'Have there been changes to the controller logic within the ICS field devices? Is there any new process has been implemented that are abnormal or anomalous? Are there any old processes that were removed that keep reappearing? Are there any of the processes', 'It seems that this anomaly might be related to:', 'Process monitoring', 'TECHNIQUE T846: REMOTE SYSTEM DISCOVERY', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (20, 'Is there any prcess that visibly consume network bandwith outside of accceptable parameters?', 'It seems that this anomaly might be related to:', 'Process use of network ', 'TECHNIQUE T846: REMOTE SYSTEM DISCOVERY', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (21, 'Are any values being passed via command line? Are features being enabled or disabled without authorization?', 'It seems that this anomaly might be related to:', 'Process command-line parameters ', 'TECHNIQUE T846: REMOTE SYSTEM DISCOVERY', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (22, 'Have any logs within control processes been identified as containing unauthorized enties? ', 'It seems that this anomaly might be related to:', 'Logs within the control process ', 'TECHNIQUE T846: REMOTE SYSTEM DISCOVERY', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (23, 'Are there any file names with unusual characters or files not found in the baseline? Have logs been reviewed for anomalies against baseline software, configurations, authorized connections, and user accounts? ', 'It seems that this anomaly might be related to:', 'Devices becoming unresponsive (recorded by event recorder or data historian)', 'TECHNIQUE T814: DENIAL OF SERVICE', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (24, 'Is there a problem with equipment in the ICS process locking, spontaneous reboot, anomalous display screen changes?', 'It seems that this anomaly might be related to:', 'Alarms for large amounts of requests or for the device becoming unresponsive', 'TECHNIQUE T814: DENIAL OF SERVICE', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (25, 'Are peripheral devices that are not normally communicating with devices now communicating? (e.g., printers, fax machines, copiers, repeaters, hubs, converters, etc.)', 'It seems that this anomaly might be related to:', 'Unnecessary messages sent to the data historian or to devices', 'TECHNIQUE T804: BLOCK REPORTING MESSAGE', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (26, 'Are of the any other observed events that have changed in the ICS processes that are not accounted by organizational communications?', 'It seems that this anomaly might be related to:', 'Device logs or alarms indicating changes to parameters', 'TECHNIQUE T836: MODIFY PARAMETER', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (27, 'Is there anomalous batch process executing outside of normal control traffic causing abnormal changes to ICS process? ', 'It seems that this anomaly might be related to:', 'Lye levels in water increased from 100 to 11,100 parts per million', 'TECHNIQUE T836: MODIFY PARAMETER', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (28, 'While checking File Itegrity Monitor (FIM) systems have there been any alerts or notifications about ICS files being changed? Are there any of the processes that seem to be or were sabotaged or malfunctioning?  Is there unusual file names or additions or ', 'It seems that this anomaly might be related to:', 'File monitoring systems detecting file deletion', 'TECHNIQUE T809: DATA DESTRUCTION', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (29, 'Devices that are under automated control should be exhibiting behavior that is synchronized with the commands sent by the OPC or control server or the HMI. Is there any anomalous behavior coming to/from devices that is outside the baseline? Have any netwo', 'It seems that this anomaly might be related to:', 'Process command-line parameters changing or not accepting certain commands', 'TECHNIQUE T809: DATA DESTRUCTION', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (30, 'Have there been changes to the controller logic and or commad files within or between the ICS field devices? Were there any out of normal or anomalous firmware pushes or pulls?', 'It seems that this anomaly might be related to:', 'Process monitoring systems picking up on unknown processes running or installing files', 'TECHNIQUE T809: DATA DESTRUCTION', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (31, 'Configuration files changed without user or system admin action? Configuration changes to software made without user or system admin action? Were there any out of normal or anomalous firmware pushes or pulls?', 'It seems that this anomaly might be related to:', 'Firmware updates to SIPROTEC relays causing them to fail to perform functions', 'TECHNIQUE T881: SERVICE STOP', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (32, 'Has the server/workstation registry been checked for anomalous processes? Are there unknown executing processes that have no name or icon? Are there unknown executing processes that have no description or company name?', 'It seems that this anomaly might be related to:', 'Modified Windows Registry keys', 'TECHNIQUE T881: SERVICE STOP', 'Based on your answers, there is a high likelihood  of malicious activity:  Recommendation: Further investigation')
INSERT INTO [dbo].[CYOTE_QUESTIONS] ([Question_Id], [Question_Text], [Intro], [Symptom], [Techniques], [Recommendation]) VALUES (33, 'There is curently no attack technique associated with this data source', 'There is curently no attack technique associated with this data source', 'There is curently no attack technique associated with this data source', 'There is curently no attack technique associated with this data source', 'There is curently no attack technique associated with this data source')
