INSERT INTO [dbo].[GEN_FILE] ([Gen_File_Id], [File_Type_Id], [File_Name], [Title], [Name], [File_Size], [Doc_Num], [Comments], [Description], [Short_Name], [Publish_Date], [Doc_Version], [Summary], [Source_Type], [Data], [Is_Uploaded]) VALUES (6087, 31, 'CIS_Controls_v8.pdf', 'CIS Critical Security Controls Version 8', 'CSC Version 8', 1041298, 'NONE', NULL, 'The CIS Controls reflect the combined knowledge of experts from every part of the ecosystem to create, adopt, and support CIS Controls.', 'CSC V8', NULL, NULL, 'The CIS Controls reflect the combined knowledge of experts from every part of the ecosystem (companies, governments, individuals), with every role (threat responders and analysts, technologists, information technology (IT) operators and defenders, vulnerability-finders, tool makers, solution providers, users, policy-makers, auditors, etc.), and across many sectors (government, power, defense, finance, transportation, academia, consulting, security, IT, etc.), who have banded together to create, adopt, and support the CIS Controls.', NULL, NULL, 0)
INSERT INTO [dbo].[MATURITY_GROUPING_TYPES] ([Type_Id], [Grouping_Type_Name]) VALUES (8, 'Section')
INSERT INTO [dbo].[MATURITY_GROUPING_TYPES] ([Type_Id], [Grouping_Type_Name]) VALUES (1001, 'Top Level Observable Classification')
INSERT INTO [dbo].[MATURITY_MODELS] ([Maturity_Model_Id], [Model_Name], [Questions_Alias], [Answer_Options], [Analytics_Rollup_Level], [Model_Description], [Model_Title]) VALUES (7, 'VADR', 'Practices', 'Y,N,A', 2, 'The VADR maturity model enables participants to perform assessments virtually. Virtual assessments include the same elements that make up a traditional VADR: Architecture Design Review, System Configuration and Log Review, as well as Network Traffic Analysis.', 'TSA Validated Architecture Design Reviews (VADR)')
INSERT INTO [dbo].[MATURITY_MODELS] ([Maturity_Model_Id], [Model_Name], [Questions_Alias], [Answer_Options], [Analytics_Rollup_Level], [Model_Description], [Model_Title]) VALUES (8, 'CIST', 'Questions', 'Y,N', 2, 'The CIS goal is to assess the foundational and essential cybersecurity practices of an organization''s critical service to identify dependencies, capabilities and emerging effects of the current cybersecurity posture. CIS focuses on a service-based-view versus a programmatic-view of cybersecurity. Critical services are assessed against more than 80 cybersecurity controls grouped under five top-level domains: cybersecurity management, cybersecurity forces, cybersecurity controls, cyber incident response, and cyber dependencies. A CIS provides your organization with an effective assessment of cybersecurity controls in-place for critical services to support cybersecurity planning, resource allocation, and performance evaluation.', 'CISA Cyber Infrastructure Survey (CIS)')
INSERT INTO [dbo].[MATURITY_MODELS] ([Maturity_Model_Id], [Model_Name], [Questions_Alias], [Answer_Options], [Analytics_Rollup_Level], [Model_Description], [Model_Title]) VALUES (9, 'CYOTE', 'Questions', 'Y,N', 1, 'CyOTE is a high-priority CESER investment to enhance energy sector threat detection of anomalous behavior potentially indicating malicious cyber activity in OT networks. Specifically, the CyOTE methodology and detection capabilities enable asset owners to better evaluate their production and transmission of energy and take mitigating measures when appropriate.', 'Cybersecurity for the Operational Technology Environment (CyOTE)')
