INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2302, 'Cybersecurity Forces', '', 8, 11, NULL, 1, 8, '212', NULL, NULL)
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2303, 'Cybersecurity Controls', '', 8, 12, NULL, 1, 8, '213', NULL, NULL)
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2304, 'Incident Response', '', 8, 13, NULL, 1, 8, '214', NULL, NULL)
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2305, 'Dependencies', '', 8, 14, NULL, 1, 8, '215', NULL, NULL)
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2306, 'Cybersecurity Leadership', 'For purposes of this evaluation cybersecurity management includes the leadership roles and responsibilities (e.g., governance), physical documentation, lifecycle tracking, information sharing (e.g., threat information), accreditation, assessment, and audits.', 8, 1, 2301, 2, 8, '216', NULL, '1')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2307, 'Cybersecurity Architecture', '', 8, 2, 2301, 2, 8, '217', NULL, NULL)
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2308, 'Change Management', 'Change management is the control procedures required to change the baseline configuration of a Service. The baseline configuration is the set of specifications for a Service that has been formally reviewed and agreed on at a given point in time and can be changed only through formal change procedures. Configuration controls include controlling modifications to hardware, firmware, software, and documentation to protect the information Service against improper modifications prior to, during and after Service implementation.', 8, 3, 2301, 2, 8, '218', NULL, '5')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2309, 'Lifecycle Tracking', 'For purposes of this evaluation, a life cycle is defined in the phases of which it passes through initiation, development, operation, and termination.', 8, 4, 2301, 2, 8, '219', NULL, '6')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2310, 'Assessment and Evaluations', 'Does the facility utilize formal, external cybersecurity guidance and standards for identifying and implementing cybersecurity controls (management, operational, and technical)?The purpose of capturing accreditation and assessment information is to see if the facility utilizes external standards to develop policies regarding cybersecurity including policies that affect people, processes, and equipment. This information is to help to compare across sectors and amongst different standards.', 8, 5, 2301, 2, 8, '220', NULL, '7')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2311, 'Cybersecurity Plan', 'Organizations must develop, document, update, and implement: the security plans or the planned security plans for organizational information Services that describe the security controls to be in place and the rules of behavior for individuals accessing the information Services. The facility has documentation that addresses cybersecurity or cyber service continuity. A cyber service involves addressing continuity of operations, business continuity, cyber disaster recovery, etc. These plans may exist separately or could be included in the organizations overall plans but should address cyber specifically.', 8, 6, 2301, 2, 8, '221', NULL, '8')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2312, 'Cybersecurity Exercises', 'For purposes of the cybersecurity exercise questions, if none of the suggested purposes provided are marked, it is assumed that cybersecurity exercises are done for compliance reasons only.', 8, 7, 2301, 2, 8, '222', NULL, '9')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2313, 'Information Sharing', '', 8, 8, 2301, 2, 8, '223', NULL, NULL)
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2314, 'Personnel', '', 8, 9, 2302, 2, 8, '224', NULL, '12')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2315, 'Cybersecurity Training', 'Cybersecurity training has become policy in most organizations but the standards used are different among each organization. This cybersecurity training question set is here to understand what the median is for type, frequency, and purpose of these training program practices.', 8, 10, 2302, 2, 8, '225', NULL, '13')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2316, 'Authentication and Authorization Controls', 'The purpose of this question set is to find the basis of authentication and authorization controls used on the CCS within the evaluated organization. Common practices such as administrator privileges, user privileges, and password management are assessed.', 8, 11, 2303, 2, 8, '226', NULL, '14')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2317, 'Access Controls', '', 8, 12, 2303, 2, 8, '227', NULL, NULL)
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2318, 'Cybersecurity Measures', '', 8, 13, 2303, 2, 8, '228', NULL, NULL)
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2319, 'Information Protection', 'For purposes of this evaluation, information protection for sensitive information is sought to find out that it is identified and properly managed.', 8, 14, 2303, 2, 8, '229', NULL, '20')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2320, 'User Training', 'The purpose of these questions in this section is not to find out what type of training but to find out when the user is trained and when the user receives access to network.', 8, 15, 2303, 2, 8, '230', NULL, '21')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2321, 'Defense Sophistication and Compensating Controls', 'For purposes of this evaluation best judgment is to be used for defense sophistication/compensating controls. Examples of this are moving target defense, diverse platforms, etc.', 8, 16, 2303, 2, 8, '231', NULL, '22')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2322, 'Incident Response Measures', 'For purposes of this evaluation, an incident response plan should be documented in its full form. It should be agreed on and signed off by all officials. All personnel should know the plan and be fully aware of it. This incident response plan should contain items of how to respond to incidents, emergencies, and smaller events. It should layout key plans that the organization has practiced in case of an incident.', 8, 17, 2304, 2, 8, '232', NULL, '23')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2323, 'Alternate Site and Disaster Recovery', 'For purposes of this evaluation, severely impacted means that the organization is running at a level considered “significantly lower output to no output” of work.', 8, 18, 2304, 2, 8, '233', NULL, '24')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2324, 'Dependencies - Data at Rest', '', 8, 19, 2305, 2, 8, '234', NULL, '25')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2325, 'Dependencies - Data in Motion', '', 8, 20, 2305, 2, 8, '235', NULL, '26')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2326, 'Dependencies - Data in Process', '', 8, 21, 2305, 2, 8, '236', NULL, '27')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2327, 'Dependencies - End Point Systems', '', 8, 22, 2305, 2, 8, '237', NULL, '28')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2328, 'Inventory', 'A critical cyber asset inventory would include at minimum the network addresses, machine names, purpose of each Service and asset owner responsible for each device. It may also include every device with an IP address, including servers, desktops, network equipment (routers, switches, firewalls, etc.), printers, storage area networks, VOIP, multi-homes addresses, virtual addresses, mobile phones, tablets, laptops, and other portable devices that store or process data.', 8, 1, 2307, 3, 8, '238', NULL, '2')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2329, 'System Architecture', 'For this survey, an identified documented CCS asset security architecture should include all CCS cyber assets. The purpose of these questions are to additional assets into the architecture document and how frequently it is reviewed and updated. A documented system architecture could include the following: routers, switches, computers, servers, firewalls, VPNs, remote desktops, virtual machines, networks, etc. For the purpose of this survey, system configuration monitoring tools examples are: IBM Tivoli, IBM BigFix, Apache Subversion, & Perforce.', 8, 2, 2307, 3, 8, '239', NULL, '3')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2330, 'Security Architecture', '', 8, 3, 2307, 3, 8, '240', NULL, '4')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2331, 'External Information Sharing', 'Organizations have varying criteria for declaring a cybersecurity incident. However, in general terms, a cybersecurity incident is an event that violates written or implied security policies. Depending on the organization, examples might include spear phishing campaigns, stolen data, and denial service attacks. The purpose of validation back to the organization is to allow for better reporting standards. A “Yes” answer means the organization refers back to the document owner providing some feedback that this information was helpful or not to them. A “No” answer means the organization does not give any feedback to originating organization.', 8, 1, 2313, 3, 8, '241', NULL, '10')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2332, 'Internal Information Sharing', '', 8, 2, 2313, 3, 8, '242', NULL, '11')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2333, 'Access Paths', 'Unauthorized access is: an individual gains logical or physical access without permission to a network, Service, application, data, or other resource.', 8, 1, 2317, 3, 8, '243', NULL, '15')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2334, 'Remote Access Controls', 'Remote Access allows connectivity to the internal network from the outside. User controls can include only allowing designated users to connect remotely, vs. all users; use of secure tokens; changing default passwords on remote devices; etc.', 8, 2, 2317, 3, 8, '244', NULL, '16')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2335, 'Malicious Code Controls', 'Does the organization employ any real time or near real time countermeasures against malicious code.', 8, 1, 2318, 3, 8, '245', NULL, '17')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2336, 'Monitoring and Scanning', 'How often and for what purposes does the organization monitor and scan the network are the main areas looked at.', 8, 2, 2318, 3, 8, '246', NULL, '18')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2337, 'Security and Event Log', 'For purposes of this evaluation, event logging is log retention of services such as networks, endpoints, applications, etc.', 8, 3, 2318, 3, 8, '247', NULL, '19')
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2338, 'Network', 'Anamalies that are seen on the network or can be identifed as associated with the network', 9, 1, NULL, 1, 1001, '1', 'Net', NULL)
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2339, 'Control System', 'Anamalies that are observed in the control system', 9, 2, NULL, 1, 1001, '1', 'ICS', NULL)
INSERT INTO [dbo].[MATURITY_GROUPINGS] ([Grouping_Id], [Title], [Description], [Maturity_Model_Id], [Sequence], [Parent_Id], [Group_Level], [Type_Id], [Title_Id], [Abbreviation], [Title_Prefix]) VALUES (2340, 'Physical Observations', 'Anamalies that are observed as part of plant operations (e.g. smell, hear, touch, or see) but that are not observed through the ICS or IT Networks', 9, 3, NULL, 1, 1001, '1', 'Physical', NULL)
INSERT INTO [dbo].[MATURITY_LEVELS] ([Maturity_Level_Id], [Level], [Level_Name], [Maturity_Model_Id]) VALUES (16, 1, 'Level 1', 7)
