INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5107, 'CM.PM.04', 'Are updates to the system tested in a non-production environment?', '<div><strong>Control Objective</strong></div><div class="mb-2">Analyze changes to the system in a separate test environment before implementation in an operational environment, looking for security and privacy impacts due to flaws, weaknesses, incompatibility, or intentional malice.</div><div><strong>Supplemental Guidance</strong></div><div class="mb-2">A separate test environment requires an environment that is physically or logically separate and distinct from the operational environment. The separation is sufficient to ensure that activities in the test environment do not impact activities in the operational environment and that information in the operational environment is not inadvertently transmitted to the test environment. Separate environments can be achieved by physical or logical means. If physically separate test environments are not implemented, organizations determine the strength of mechanism required when implementing logical separation.</div><div><strong>For further information, see related controls</strong></div><div class="mb-2">SA-11, SC-7.</div>', '', '', 1, 7, 7, NULL, 1308, 0, '', NULL, NULL, NULL)
