INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5163, 'MP.RM.04', 'Is the capability for automatic execution of code on removable media disabled?', '<div><strong>Control Objective</strong></div><div class="mb-2">Prevent the automatic execution of mobile code in [Assignment: organization-defined software applications] and enforce [Assignment: organization-defined actions] prior to executing the code.</div><div><strong>Supplemental Guidance</strong></div><div class="mb-2">Actions enforced before executing mobile code include prompting users prior to opening email attachments or clicking on web links. Preventing the automatic execution of mobile code includes disabling auto-execute features on system components that employ portable storage devices, such as compact discs, digital versatile discs, and universal serial bus devices.</div><div><strong>For further information, see related controls</strong></div><div class="mb-2">None.</div>', '', '', 1, 6, 7, NULL, 1332, 0, '', NULL, NULL, NULL)
