INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5172, 'PO.CP.04', 'Is responsibility for the cybersecurity program assigned to a role with requisite authority?', '<div><strong>Control Objective</strong></div><div class="mb-2">Appoint a senior agency information security officer with the mission and resources to coordinate, develop, implement, and maintain an organization-wide information security program.</div><div><strong>Supplemental Guidance</strong></div><div class="mb-2">The senior agency information security officer is an organizational official. For federal agencies (as defined by applicable laws, executive orders, regulations, directives, policies, and standards), this official is the senior agency information security officer. Organizations may also refer to this official as the senior information security officer or chief information security officer.</div><div><strong>For further information, see related controls</strong></div><div class="mb-2">None.</div>', '', '', 1, 5, 7, NULL, 1334, 0, '', NULL, NULL, NULL)
