INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5913, '', '1.1 Is there a manager/department in charge of day-to-day cybersecurity management?', '<div>Management of cybersecurity is considered a primary function when it is over 51% of the&#160;<span>work you do. This question aims to determine whether there is a single person or single group&#160;</span><span>specifically in charge of all cybersecurity versus multiple entities managing different aspects of</span></div><div>cybersecurity.</div>', '', '', 1, 1, 8, NULL, 2306, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5914, '', '1.2 Are there any other cybersecurity leaders with cyber responsibilities?', '<div>This aims to assess the diversity of cybersecurity leadership and to identify their focus areas.&#160;<span>Some additional responsibilities could include: firewalls, server setup or maintenance, setting&#160;</span><span>up users or passwords, etc.</span></div><div><span><br></span></div><div>&#183; <u>Operation/Functional</u>: To ensure systems are running functionally and smoothly</div><div>&#183; <u>Service</u>: To work towards providing some type of services perhaps to an end user</div><div>&#183; <u>Enterprise/Governance</u>: At an organizational level</div>', '', '', 1, 4, 8, NULL, 2306, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5915, '', '1.3 Is there a third-party contract arrangement for primary cyber management and/or operational functions for this Critical Services?', '<div>Third-party contracts for cyber management or operational functions includes any/all cyber&#160;<span>assessments, cyber documentation, IT audits, and/or additional work that is not done by the&#160;</span><span>primary organization. This statement should not be &#8220;true&#8221; if the first portion was answered&#160;</span><span>affirmatively. Does the organization manage its own cybersecurity or have they out-sourced&#160;</span><span>all or part of their cybersecurity needs?</span></div><div><span><br></span></div><div>If yes, for what types of cybersecurity has the organization decided to purchase</div><div>assistance?</div><div><br></div><div>&#183; <u>Intrusion prevention</u>: An internet service provider (ISP) might provide this service.</div><div>&#183; <u>Monitoring</u>: Is there a piece of software that is installed in order to monitor systems&#160;<span>remotely?</span></div><div>&#183; <u>Incidents</u>: Is there a tracking system in place for events related to cybersecurity?</div>', '', '', 1, 5, 8, NULL, 2306, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5916, '', '1.4 Are cybersecurity contractors or vendors used for day-to-day work?', '<u>Vendors</u>: Does the organization depend upon external support for daily operations?', '', '', 1, 6, 8, NULL, 2306, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5919, '', '2.1 Is there an inventory of all critical cyber assets for this Critical Services?', '<p>Programmable electronic devices and communication networks, including hardware,software and data. Data and cabling are considered to exist within the framework of the cyber asset and there are not separate cyber assets. </p>
