INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5925, '', '4.1 Is there a documented security architecture that includes each of the identified Critical Services assets?', 'Does the organization have a plan for securing the cyber assets included in the inventory?', '', '', 1, 1, 8, NULL, 2330, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5928, '', '5.1 Which option best describes the organization''s approach to cyber change management (e.g., new hardware/software, employee access)? (Check one.)', '<div>&#183; Revision Logs: Does the change management process require and collect detailed&#160;<span>information? Is this information stored?</span></div><div>&#183; Documented and distributed cyber change: Are the policies and procedures documented&#160;<span>and provided to all relevant personnel?</span></div><div>&#183; Documented and distributed change management procedures: Are there procedures but no&#160;<span>policy?</span></div><div>&#183; Ad hoc process for regulating and approving&#160;<span>changes: Are changes managed or handled&#160;</span><span>without a formal, documented process?</span></div>', '', '', 1, 1, 8, NULL, 2308, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5929, '', '5.2 Does the organization use any distribution restrictions to validate software requests against an approved software list to allow installation on the Critical Services?', 'Has the organization identified a set of approved software? Is there a list of approved vendors?', '', '', 1, 2, 8, NULL, 2308, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5930, '', '5.3 Does the organization have a standard to establish and maintain a system configuration to include secure, build, image, or configure for the Critical Services?', '<div>Use of disk or system imaging software, backups, or non-manufacturer configuration disks to&#160;<span>preserve system configurations.</span></div>', '', '', 1, 3, 8, NULL, 2308, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5931, '', '5.4 What measures does the organization employ to manage the configuration of this Critical Services? (Check all that apply.)', '<div>&#183; Identifies all hardware and disables all unnecessary elements (firmware): Are hardware&#160;<span>systems hardened to deny-all and allow-by-exception?</span></div><div>&#183; Identifies all software and disables all unnecessary elements: Are software systems&#160;<span>hardened to deny-all and allow-by-exception?</span></div><div>&#183; Identifies all services and disables all unnecessary elements (software-as-a-service): Are&#160;<span>service systems hardened to deny-all and allow-by-exception?</span></div><div>&#183; Identifies all operationally sensitive information: Does the organization know where all&#160;<span>sensitive information is located, for instance, on specific computer disks, databases, within&#160;</span><span>specific network segments, etc.?</span></div><div>&#183; Identifies security vulnerabilities: Uses methods such as: risk assessment, vulnerability&#160;<span>scanning, and penetration testing</span></div><div>&#183; Mitigates security vulnerabilities by implementing compensating security controls (e.g.,&#160;<span>patch, work-around, offline): Have the known weaknesses been addressed by protective&#160;</span><span>measures?</span></div><div>&#183; Strictly defines standardized service configurations: Are most or all systems configured&#160;<span>using the same or very similar method? For example, all Windows servers receive the same&#160;</span><span>Active Directory Group Policy configuration.</span></div><div><span><div>&#183; Identifies and addresses non-compliant configurations: Are exceptions&#160;<span>(systems with non-standard configurations, with special permissions, etc.)&#160;</span><span>clearly indicated and protected or monitored with special attention?</span></div><div>&#183; Defines network communication devices and means: Are the methods for&#160;<span>communicating over networks clearly identified and understood?</span></div><div>&#183; Defines portable media and access management: Are special procedures&#160;<span>defined for the use of portable media and the protection of the information that&#160;</span><span>can be transferred to portable media? For instance, since USB drives can&#160;</span><span>introduce malware, automated malware scanning should be&#160; &#160; &#160;required.</span></div></span></div>', '', '', 1, 4, 8, NULL, 2308, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5934, '', '6.1 Does the organization address the security of Critical Services assets anywhere throughout their life cycle (inception through disposal)?', 'Does the organization plan for the long-term security of systems?', '', '', 1, 1, 8, NULL, 2309, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5935, '', '6.2 Which documents does the organization retain that can demonstrate integration of cybersecurity into the Critical Services asset life cycle? (Check all that apply.)', '<div>&#183; Requirements analysis: What are the requirements for the systems and applications? How&#160;<span>can they be evaluated to ensure they perform as expected?</span></div><div>&#183; Acquisition plans and/or procedures: Are the purchasing requests retained? Do they contain&#160;<span>sufficient information to re-purchase the equipment, if necessary?</span></div><div>&#183; Implementation plans and/or procedures: What was required to build and install the cyber&#160;<span>assets? Did this require special configuration? Are the configurations documented with&#160;</span><span>sufficient detail to recover or restore the cyber assets, if necessary?</span></div><div>&#183; Operations plans and/or procedures: Are there documented procedures for operating the&#160;<span>cyber assets, such as adding accounts, performing backups and restoration, monitoring&#160;</span><span>performance and availability, etc.?</span></div><div>&#183; Change management plans and/or procedures: Is there a documented change management&#160;<span>process? What are the requirements? Is there an approval process? Are security tests&#160;</span><span>required before changes are approved?</span></div><div>&#183; Vulnerability management plans and/or procedures: Is there a document that describes how&#160;<span>vulnerabilities are identified and remediated or mitigated? Is there a document describing how&#160;</span><span>patches are applied?</span></div><div>&#183; Security accreditation/certification: Does the organization receive accreditation or&#160;<span>certification? Does the organization perform a self-assessment? Are documents created and&#160;</span><span>retained during these assessments?</span></div>', '', '', 1, 4, 8, NULL, 2309, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5936, '', '6.3 Does the organization employ procurement and contracting measures to specify and enforce security requirements for third-party service providers and vendors? (if applicable)', '<div>For purposes of this evaluation, third party vendors and service providers would be any organization&#160;<span>outside the evaluated facility that provides service or products to the evaluated facility. (e.g.,&#160;</span><span>software, hardware, electricity, water)</span></div>', '', '', 1, 5, 8, NULL, 2309, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5937, '', '6.4 Does the organization employ any of the following security controls specific to the Critical Services to prevent exploitation of vulnerabilities?', '<div>&#183; Organization routinely identifies available software security patches and updates: The&#160;<span>organization is aware of security vulnerabilities and patches, but does not ensure that all&#160;</span><span>systems are patched as soon as possible.</span></div><div>&#183; Organization applies appropriate patches and updates to systems as soon as possible, given&#160;<span>critical operational and testing requirements: All vulnerabilities are patched or mitigated as&#160;</span><span>soon as possible.</span></div>', '', '', 1, 6, 8, NULL, 2309, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5938, '', '6.5 Approximately what percentage of Critical Services systems are not or cannot be updated with respect to critical vulnerabilities? (e.g. legacy system or business reason- i.e., break software application)', '<div>A system that is not or cannot be updated with respect to critical vulnerabilities would be mean:&#160;<span>outdated operating system or a business reason - break hardware or software doesn''t work.</span></div>', '', '', 1, 7, 8, NULL, 2309, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5939, '', '6.6 If the organization has Critical Services systems that are not or cannot be updated with respect to critical vulnerabilities, approximately what percentage of these systems have compensating security controls in place??', '', '', '', 1, 8, 8, NULL, 2309, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5942, '', '7.1 Does your organization follow a cybersecurity standard(s) of practice?', '<div>There are formal industry, government standards with respect to cybersecurity, as well as informal&#160;<span>best-practices methodology. This question refers to any information technology or cybersecurity&#160;</span><span>methodology your organization uses for their program.</span></div>', '', '', 1, 2, 8, NULL, 2310, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5943, '', '7.2 Does the organization conduct cybersecurity assessments/evaluations to identify potential security gaps or weaknesses to any Critical Services assets?', '<div>This question refers to any formal or informal system testing conducted by your organization. System&#160;<span>tests can be computer or network penetration testing, vulnerability assessments, or cybersecurity&#160;</span><span>process review because of change in standard of practice.</span></div>', '', '', 1, 5, 8, NULL, 2310, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5946, '', '8.1 Does the organization have a defined, documented cybersecurity policy?', '<div>Defined and documented cybersecurity policy refers to a formal governance that is conducted by&#160;<span>your organization. For example, new hires may be introduced to the rules and regulations on the&#160;</span><span>computer use, processes for information technology incident response, etc. Policy may also include&#160;</span><span>access controls for World Wide Web or the intranet and the Bring Your Own Device (BYOD) rules.</span></div>', '', '', 1, 3, 8, NULL, 2311, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5947, '', '8.2 Is there a Cybersecurity Plan covering this Critical Services?', '<div>This question is to find out if your organization has a broad information technology security&#160;<span>management plan or if you manage IT by sectors. You may also have some sectors actually planned&#160;</span><span>and managed, but not others. For example, you may control who has access to industrial control&#160;</span><span>systems or limit the number if IT admins, or limit which websites are accessible from your network.</span></div>', '', '', 1, 4, 8, NULL, 2311, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5950, '', '9.1 Does the organization conduct cybersecurity exercises?', '<div>The question refers to whether your organization conducts exercises to determine best mitigation,&#160;<span>response, or replacement methodology in case of CCS failure or loss.</span></div>', '', '', 1, 1, 8, NULL, 2312, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5953, '', '10.1 Does the organization, specific to the Critical Services, share cybersecurity information with outside organizations?', 'This question is to find out if your organization distributes cybersecurity incidents information to outside entities; shared information can be from a forensics investigation on the one hand, up through a simple intrusion confirmation on the other.', '', '', 1, 1, 8, NULL, 2331, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5954, '', '10.2 For the purpose of securing the Critical Services, does the organization receive vulnerability information, cybersecurity-related bulletins, advisories, and/or alerts from an external source?', 'This question refers to your organization''s awareness on cybersecurity vulnerabilities; the awareness may be gained through formal/informal working groups, web forum-based or in-person participation in exchange environments.', '', '', 1, 2, 8, NULL, 2331, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5955, '', '10.3 For the purpose of securing the Critical Services, does the organization receive threat information, cybersecurity-related bulletins, advisories, and/or alerts from an external source?', 'This question refers to your organization''s awareness on cybersecurity threats; the awareness may be gained through formal/informal working groups, web forum-based or in-person participation in exchange environments.', '', '', 1, 3, 8, NULL, 2331, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5956, '', '10.4 Does the organization report cybersecurity incidents to outside organizations, specific to the Critical Services?', 'This question is to find out if your organization reports incidents to outside entities, as opposed to share incident information. Both sharing and reporting maybe required or voluntary.', '', '', 1, 4, 8, NULL, 2331, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5957, '', '10.5 Does anyone from the organization actively participate in local or regional cybersecurity forums (e.g., exchange of lessons learned, best practices, training)?', 'This question refers to your organization''s participation in cybersecurity forums; the forums will give you awareness on threats, vulnerabilities, best practices, through formal/informal working groups, web forum or in-person participation in exchange environments.', '', '', 1, 5, 8, NULL, 2331, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5960, '', '11.1 For the purpose of the Critical Services, does the organization notify or communicate cybersecurity information to personnel?', 'A “No” response means that no security information is communicated to company personnel (e.g., no additional information other than emergency plan information - evacuation or fire drill information). Specific security incident information is for an actual security incident (e.g., suspicious people have been observed around the organization back doors, a change in NTAS level, or how to thwart known attempts at hacking the company cyber servers).', '', '', 1, 1, 8, NULL, 2332, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5963, '', '12.1 Are the following positions formalized? (Check all that apply.)', '<div>&#183; Within your organization: A single person may fill several of the positions. The point of the question is&#160;<span>identifying whether the organization has formal positions with respect to cybersecurity of the&#160;</span><span>organization. One person within the organization may hold several of these roles.</span></div><div>&#183; Within the CCS environment: A single person may fill several of the positions. The point of the&#160;<span>question is to identify whether the organization has formal positions with respect to cybersecurity of&#160;</span><span>the CCS. These positions are more narrowly and specifically focused on the CCS.</span></div>', '', '', 1, 1, 8, NULL, 2314, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5964, '', '12.2 Do you have a policy that authorizes and holds accountable the personnel having these assignments?', '', '', '', 1, 5, 8, NULL, 2314, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5965, '', '12.3 Are background checks conducted for organizational and supporting personnel?', '<div>It is understood that there may be limitations to background checks in some states or for foreign&#160;<span>contractors. The intent of the question is to determine if there is a process for background checks.&#160;</span><span>Often background checks are a reasonable action to dissuade insider threats or to ensure effective&#160;</span><span>hiring practices. If foreign contractors do not have background checks, but are allowed to be in the&#160;</span><span>facility without restrictions, then do not select contractors/support functions.</span></div>', '', '', 1, 10, 8, NULL, 2314, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5968, '', '13.1 Do cybersecurity personnel involved in day-to-day Critical Services operations receive cybersecurity training?', '<div>Note that question focuses on cybersecurity personnel only. The question consists of four&#160;<span>parts:</span></div><div><span><br></span></div><div>1.) Motivation</div><div>2.) Delivery mechanism</div><div>3.) Frequency</div><div>4.) Subject matter/content</div>', '', '', 1, 1, 8, NULL, 2315, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5969, '', '13.2 Are cyber personnel trained on the cybersecurity plan?', '', '', '', 1, 5, 8, NULL, 2315, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5970, '', '13.3 Has the organization established and documented a minimum level of training, education and/or experience required for cybersecurity personnel related to the Critical Services?', '', '', '', 1, 6, 8, NULL, 2315, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5971, '', '13.4 Does the organization manage skills management as part of the performance monitoring process related to the Critical Services?', '', '', '', 1, 9, 8, NULL, 2315, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5974, '', '14.1 Has the organization established a process for authentication and authorization (i.e., identity proofing, registration, role-management) to limit access to the Critical Services to only authorized persons?', 'Examples include identity proofing, registration, and role-management.<div><br></div><div><div><i>Identity Proofing</i></div><div><i><br></i></div><div>For purposes of this evaluation, identity proofing is divided into 5 categories: risk-based,&#160;<span>controls-based, best-practices, vendor-based, some other basis.</span></div><div><br></div><div>&#183; Risk-based: is a non-static authentication system which takes into account the profile of a&#160;<span>user requesting access to system. An example is asking additional security question if they&#160;</span><span>login from a different computer or IP.</span></div><div>&#183; Controls-based: is an approach that restricts system access to authorized users. This&#160;<span>means that users have to authenticate based on their roles and they are only deemed their&#160;</span><span>privileges based off what they need.</span></div><div>&#183; Best-practices: is an example of authentication such as two-step verification. Using RSA&#160;<span>keys and Cryptocards are examples of second steps of verification. Another example is that&#160;</span><span>DISA produces a STIG and most government institutions follow that STIG.</span></div><div>&#183; Vendor-based: example is: Microsoft recommends that a virus scanner is needed.</div><div>&#183; The term &#8220;<b>Some other basis</b>&#8221; will be the catch all.</div></div>', '', '', 1, 1, 8, NULL, 2316, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5975, '', '14.2 Which of the following measures does the organization employ to control authorization? (Check all that apply.)', '<div>&#183; Access control based upon functional isolation requirements: Users, Administrators,&#160;<span>Contractors</span></div><div>&#183; Data loss prevention technology: Symantec DLP, Cisco DLP</div><div>&#183; Management review of access privileges per level at least annually: Administrators are&#160;<span>approved for a strict time period and reviewed</span></div><div>&#183; Accounts are unique to individuals or functions: John Doe - jdoe or Administrators&#160;<span>admindoe</span></div><div>&#183; An established functional or business requirement: John Doe is an Administrator of the&#160;<span>business network and should be admin of just that network</span></div><div>&#183; Rights can be temporarily suspended: John Doe is taking a sabbatical - all admin and user&#160;<span>rights are suspended until his return on 10/31/15</span></div>', '', '', 1, 7, 8, NULL, 2316, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5976, '', '14.3 Which of the following measures does the organization employ to control administrator privileges (to include contractors performing administrative functions)? (Check all that apply.)', '<div>&#183; All user accounts with administrator privileges are approved by management: Functional&#160;<span>usage, management approval, logged, or trained before administrator privileges are given</span></div><div>&#183; All users with administrator privileges are trained on cybersecurity requirements: The&#160;<span>requirements for cybersecurity are defined and the administrator understands them and their&#160;</span><span>consequences</span></div><div><span><div>&#183; All accounts with administrative level access are centrally logged and audited: Actions&#160;<span>requiring administrator access such as username creation or privilege modification are logged</span></div></span></div>', '', '', 1, 8, 8, NULL, 2316, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5977, '', '14.4 Does the organization practice the concept of least privileges (i.e., users are only granted access to the information, files, and applications required to fulfill their roles and responsibilities) within the Critical Services for all accounts?', '', '', '', 1, 11, 8, NULL, 2316, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5978, '', '14.5 Is username/password the primary means of user authentication to the Critical Services?', '<div>&#183; Organization enforces a complexity and length requirement on the password: Must be X&#160;<span>characters with both upper and lower case and have a special character</span></div><div>&#183; Organization enforces a reuse policy on passwords forbidding the use of recently used&#160;<span>passwords: The password used cannot be one of the previously used passwords</span></div><div>&#183; Organization enforces 1 time hashed based passwords: RSA, Kerberos</div><div>&#183; Organization disallows shared passwords forcing each account holder and service to have its&#160;<span>own username/password: Organization does not have a central account - admin, admin1</span></div>', '', '', 1, 12, 8, NULL, 2316, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5979, '', '14.6 What additional properties of authentication are employed for the Critical Services?', '<div>&#183; Additional layers of authentication: e.g., sequential (username/password then RSA)</div><div>&#183; Account lock-out: (after a defined number of failures)</div><div>&#183; Unique forms of authentication: multiple-factor authentication such as a generated token, RSA&#160;<span>keyfob, Smart card, or USB/hasp key</span></div>', '', '', 1, 13, 8, NULL, 2316, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5980, '', '14.7 If the primary means of authentication failed, has the organization determined that compensating controls would provide sufficient authentication?', 'If local directory went down would a general user/password be sufficient for security.', '', '', 1, 14, 8, NULL, 2316, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5981, '', '14.8 Does the organization have a protocol for removing, suspending or modifying user accounts upon change of employment?', '<div>&#183; Following an adverse human resources action, when is an account modified, deleted, or&#160;<span>de-activated? (I.e., fired, quits (bad terms))</span></div><div>&#183; When a user leaves the organization, when is an account modified, deleted, or de-activated?&#160;<span>(i.e., lay off, quits (&#34;good&#34; terms))</span></div><div>&#183; When a user transfers into a new role, when is the account modified? This can include either an&#160;<span>increase/decrease in user privileges, a move to a new organizational group, etc.</span></div><div>&#183; Does the organization test the account modification, deletion, and/or de-activation process as&#160;<span>part of its security assessments and evaluations? Is a verification done to ensure that John&#160;</span><span>Doe was removed completely?</span></div>', '', '', 1, 15, 8, NULL, 2316, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5982, '', '14.9 Does the organization have a protocol for monitoring user activity after changes in employment related to termination?', '', '', '', 1, 16, 8, NULL, 2316, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5985, '', '15.1 Has the organization established a business requirement for every access path to/from the Critical Services?', 'Each path has a business requirement for accessing or leaving the CCS.', '', '', 1, 1, 8, NULL, 2333, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5986, '', '15.2 Does the organization implement security controls to limit access across the documented boundaries (e.g., firewalls, IDS port security, or rules of behavior)?', 'Does the CCS benefit from access control device(s) that restrict incoming and/or outgoing connections between the CCS and the Internet? (Check all that apply): Does the CCS benefit from access control devices?', '', '', 1, 2, 8, NULL, 2333, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5987, '', '15.3 Can a non-critical system act as a conduit (connection) between the Internet and Critical Services?', '', '', '', 1, 3, 8, NULL, 2333, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5988, '', '15.4 Which of the following security measures does the organization employ for preventing exploitation of access paths? (Check all that apply.)', '<ul><li>Inspection of inbound data communications: Firewalls, Gateways, Level3 Switches, etc.</li>
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5991, '', '16.1 Does the organization allow remote access to Critical Services assets?', '', '', '', 1, 1, 8, NULL, 2334, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5994, '', '17.1 Does the organization employ any of the following security controls to prevent malicious code from exploiting the Critical Services? (Check all that apply.)', '', '', '', 1, 1, 8, NULL, 2335, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5997, '', '18.1 Which of the following cybersecurity measures does the organization employ for monitoring of networks related to the Critical Services? (Check all that apply.)', '', '', '', 1, 1, 8, NULL, 2336, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (5998, '', '18.2 For what purpose does the organization perform monitoring? (Check all that apply.)', '', '', '', 1, 2, 8, NULL, 2336, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6001, '', '19.1 Does the organization maintain security and event logs?', '<ul><li>There is a log retention policy: logs are stored for longer than 24 hours</li>
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6004, '', '20.1 Is operationally sensitive information (e.g., network diagrams, Critical Services inventories) identified and categorized for the Critical Services?', 'Operationally sensitive - HIPPA, PII, network diagrams, CCS inventories, etc.', '', '', 1, 1, 8, NULL, 2319, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6005, '', '20.2 Is there a security review before information is released outside of operations (partner sharing, public release, etc.)?', '', '', '', 1, 3, 8, NULL, 2319, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6008, '', '21.1 Does the organization provide training on cybersecurity for Critical Services users/operators on a regular basis?', '<div>Review of CCS policies, cybersecurity training, roles and responsibilities, acceptable use,&#160;<span>password policies.</span></div>', '', '', 1, 1, 8, NULL, 2320, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6011, '', '22.1 Does your organization employ additional advanced tactics, strategies and/or specific layered defenses to compensate for a loss of primary controls?', 'Examples may include platform diversity, moving target defense, etc.', '', '', 1, 1, 8, NULL, 2321, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6014, '', '23.1 Does the organization have predefined plans for responding to cybersecurity incidents specific to the Critical Services?', '<div>A predefined plan could be a simple checklist if step-by-step instructions for a user or a&#160;<span>manager after the incident is suspected or identified. It could also be an elaborate collection of&#160;</span><span>detailed instructions on first and secondary response action.</span></div>', '', '', 1, 2, 8, NULL, 2322, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6015, '', '23.2 Is there a written contract with entities other than emergency responders to perform incident response specific to the Critical Services (e.g. other organizations, other companies, contract response companies, industry response networks)?', '<div>Do you know of response individuals or teams outside of your organizations that are expected&#160;<span>to triage and manage the incident? This can be computer forensic teams, public relations&#160;</span><span>representatives, personnel investigators, etc.</span></div>', '', '', 1, 3, 8, NULL, 2322, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6018, '', '24.1 Once the Critical Services is lost (without considering any redundant or alternative mode), what percentage of normal business functions are lost or degraded?', '<div>Critical Cyber System outage or loss impact will depend on the severity of an outage. If your&#160;<span>whole site is lost, the impact will be moving to alternative location, if a mail server is lost, the&#160;</span><span>impact may be minimal due to other means of communications.</span></div>', '', '', 1, 1, 8, NULL, 2323, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6019, '', '24.2 Once the Critical Services is lost (without considering any redundant or alternative mode), within what time period will the business be severely impacted?', '<div>If the outage of Critical Cyber Service occurs, how quickly are you likely to see the impact on&#160;<span>your operations?</span></div>', '', '', 1, 2, 8, NULL, 2323, 0, '', NULL, 'min-hr-day', NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6020, '', '24.3 Should your site become inoperable, do you have access to an alternative location?', '<div>This question is to find out your estimate on how long it may take to move your critical&#160;<span>information technology operations such as industrial control management, data management&#160;</span><span>and distribution, communications, to an alternate location.</span></div>', '', '', 1, 3, 8, NULL, 2323, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6021, '', '24.4 Is there a contingency or business continuity agreement for recovery?', '<div>This question is to find out if continuity of operations agreements are in place, and how long it&#160;<span>may take to recover your original site to full operations.</span></div>', '', '', 1, 6, 8, NULL, 2323, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6022, '', '24.5 Does the organization employ measures to preserve cybersecurity of the Critical Services after a disruption or organization incident?', '', '', '', 1, 7, 8, NULL, 2323, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6023, '', '24.6 How often do you test your alternative-site procedures/capabilities?', '<div>Your alternate site is typically tested by means of a scenario based activity such as a&#160;<span>simulated critical cyber system outage or loss, requiring operations to change locations. The&#160;</span><span>test may also be a simple function check performed by information technology personnel.</span></div>', '', '', 1, 8, 8, NULL, 2323, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6024, '', '24.7 How do you test alternative-site procedures/capabilities?', '', '', '', 1, 7, 8, NULL, 2323, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6025, '', '24.8 Which of the following disaster measures does the organization have? (Check all that apply.)', '', '', '', 1, 10, 8, NULL, 2323, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6028, '', '25.1 Is data storage (e.g., servers &amp; HMI) required for the Critical Services?', '<div>&#183; <u>If traditional IT</u>: Does the system depend on a SAN or a server to function? This can&#160;<span>include a setup similar to a virtual machine and SAN interface, where storage is the&#160;</span><span>dependent variable or this can include the basic servers that may be in place in a server&#160;</span><span>client type connection. A counter example of this would be an application that lives solely on&#160;</span><span>an end point system, such as a desktop or a laptop.</span></div><div>&#183; <u>If ICS</u>: Does the system depend on a human machine interface (HMI) device to control the&#160;<span>PLCs?</span></div>', '', '', 1, 1, 8, NULL, 2324, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6031, '', '26.1 Are communications required for the organization''s cyber operations?', '', '', '', 1, 1, 8, NULL, 2325, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6034, '', '27.1 Are data processing services (mainframes, server farms, cloud providers, etc.) required for the operation of the Critical Services?', 'Does the system depend on a mainframe, server farm or cloud provider to function?', '', '', 1, 1, 8, NULL, 2326, 0, '', NULL, NULL, NULL)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6037, '', '28.1 Are end point systems (desktops, laptops, tablets, etc.) required for the operation of the Critical Services?', '<div><u>If traditional IT (No)</u>: Does the system depend on a Desktop, Tablet, or Laptop to function? This can&#160;<span>include the client side of a server client type system or standalone application on a desktop.</span></div><div><u>If ICS (Yes)</u>: Does the system depend on Programmable Logic Controllers? The goal is to capture&#160;<span>the very furthest edge systems in ICS.</span></div>', '', '', 1, 1, 8, NULL, 2327, 0, '', NULL, NULL, NULL)
