INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6048, '', 'Which approach best describes the integration of cybersecurity policy into the organization''s Critical Services asset life cycle?', '<div>Is the security plan for an asset reviewed and modified when necessary, perhaps periodically?</div><div><br></div><div>&#183; Does the plan cover only the installation of the asset and not its long-term security?</div><div>&#183; The addition of a system might require specific security requirements, but the organization&#160;<span>does not require a plan for managing the system after installation.</span></div>', '', '', 1, 2, 8, NULL, 2309, 0, '', NULL, NULL, 624)
