INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6052, '', 'In what ways are the Critical Services assets assessed? (Check all that apply.)', 'This question tries to answer how your organization assess information technology security.<div><br></div><div><div>&#183; Internal vulnerability testing: from Inside networks</div><div>&#183; External vulnerability testing: from outside network</div><div>&#183; Internal penetration testing: from Inside networks</div><div>&#183; External penetration testing: from outside network</div></div>', '', '', 1, 7, 8, NULL, 2310, 0, '', NULL, NULL, 631)
