INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6088, '', 'If the communication services functionality (switches, network, firewalls, etc.) is lost completely, within what time period will the Critical Services be severely impacted?', '<div>If the internal communication lines are destroyed how long will it take before the critical cyber&#160;<span>service is effected? As a note, this should NOT be the effect on the business service, but on the&#160;</span><span>critical cyber service. For example, a police records system may be instantly effected by the loss&#160;</span><span>of its ability to communicate remotely (I.E. 0 Minutes), but that there may be another method to&#160;</span><span>continue business.</span></div>', '', '', 1, 16, 8, NULL, 2325, 0, '', NULL, 'min-hr-day', 861)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6089, '', 'Once the functionality of the communication services (switches, network, firewalls, etc.) is lost (without considering any redundant or alternative mode), what percentage of normal cyber functions are lost or degraded?', '', '', '', 1, 16, 8, NULL, 2325, 0, '', NULL, NULL, 861)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6090, '', 'Is there a contingency/business continuity plan with the provider for restoration?', '', '', '', 1, 17, 8, NULL, 2325, 0, '', NULL, NULL, 861)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6091, '', 'Does the organization participate in the provider''s priority plan for restoration?', '', '', '', 1, 18, 8, NULL, 2325, 0, '', NULL, NULL, 861)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6092, '', 'If the primary mode of communication service is lost, is there a backup mode of communication?', '', '', '', 1, 19, 8, NULL, 2325, 0, '', NULL, NULL, 861)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6093, '', 'Once the primary mode is restored, how long will it take before full resumption of operations?', '', '', '', 1, 21, 8, NULL, 2325, 0, '', NULL, 'min-hr-day', 861)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6094, '', 'If the processing service (mainframe, cluster, etc.) is lost completely, within what time period will the Critical Services be severely impacted?', '<div>If the mainframe, server farm or cloud provider are destroyed how long will it take before the critical&#160;<span>cyber service is affected? As a note, this should NOT be the effect on the business service, but on&#160;</span><span>the critical cyber service. For example, a police records system may be instantly affected by the loss&#160;</span><span>of its mainframe (I.E. 0 Minutes), but that there may be another method to continue business.</span></div>', '', '', 1, 2, 8, NULL, 2326, 0, '', NULL, 'min-hr-day', 707)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6095, '', 'Once the availability of the processing service (mainframe, cluster, etc.) is lost (without considering any redundant or alternative mode), what percentage of normal cyber functions are lost or degraded?', '<div>If the mainframe, server farm or cloud provider are destroyed how much of an impact will it have on&#160;<span>the critical cyber service? As a note, this should NOT be the effect on the business service, but on&#160;</span><span>the critical cyber service. As a second note, you should not take into account any redundancy or&#160;</span><span>alternative modes that may have been identified in the Alternate Site Section. For example, a police&#160;</span><span>records system may have complete dependence on a mainframe (I.E. 100% loss), but that there may&#160;</span><span>be another method to continue business (such as paper and pen method or a radio method).</span></div>', '', '', 1, 3, 8, NULL, 2326, 0, '', NULL, NULL, 707)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6096, '', 'Is there a contingency/business continuity plan with the provider for restoration?', 'This plan needs to be documented via a contract or in a mutual agreed upon plan.', '', '', 1, 4, 8, NULL, 2326, 0, '', NULL, NULL, 707)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6097, '', 'Does the organization depend on external data service providers?', '', '', '', 1, 5, 8, NULL, 2326, 0, '', NULL, NULL, 707)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6098, '', 'Is the dependency provider required to notify the organization of an outage?', '<div>This should be an active notification and not a passive notification. Does the organization receive a&#160;<span>phone call, email, text stating that the service is out?</span></div>', '', '', 1, 8, 8, NULL, 2326, 0, '', NULL, NULL, 792)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6099, '', 'Do you monitor this dependency?', '<div>This needs to be monitored through an active system such as Nagios or Web Watch Bot. It should&#160;<span>not be a noticeable effect but a form of out of band notification.</span></div>', '', '', 1, 9, 8, NULL, 2326, 0, '', NULL, NULL, 792)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6100, '', 'If the endpoint systems (desktops, laptops, tablets, etc.) are no longer available, within what time period would the Critical Services be severely impacted?', '<div>If the desktop or PLCs are destroyed how long will it take before the critical cyber service is effected?&#160;<span>As a note, this should NOT be the effect on the business service, but on the critical cyber service.&#160;</span><span>For example, a police records system may be instantly effected by the loss of its laptops in the&#160;</span><span>vehicles (I.E. 0 Minutes), but that there may be another method to continue business. An ICS&#160;</span><span>example: A water system may shut down in 5 minutes if the PLCs stop functioning.</span></div>', '', '', 1, 2, 8, NULL, 2327, 0, '', NULL, 'min-hr-day', 709)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6101, '', 'Once the endpoint systems (desktops, laptops, tablets, etc) are no longer available (without considering any redundant or alternative mode), what percentage of normal cyber functions are lost or degraded?', '<div>If the desktop or PLCs are destroyed how much of an impact will it have on the critical cyber service?&#160;<span>As a note, this should NOT be the effect on the business service, but on the critical cyber service. As&#160;</span><span>a second note, you should not take into account any redundancy or alternative modes that may have&#160;</span><span>been identified in the Alternate Site Section. For example, a police records system may have&#160;</span><span>complete dependence on the laptops in its vehicles (I.E. 100% loss), but that there may be another&#160;</span><span>method to continue business (such as a paper and pen method or a radio method). A water ICS&#160;</span><span>system may cease to report information back if the PLCs are destroyed (100%), even though the&#160;</span><span>water system may still pump water.</span></div>', '', '', 1, 3, 8, NULL, 2327, 0, '', NULL, NULL, 709)
INSERT INTO [dbo].[MATURITY_QUESTIONS] ([Mat_Question_Id], [Question_Title], [Question_Text], [Supplemental_Info], [Category], [Sub_Category], [Maturity_Level], [Sequence], [Maturity_Model_Id], [Parent_Question_Id], [Grouping_Id], [Ranking], [Examination_Approach], [Short_Name], [Mat_Question_Type], [Parent_Option_Id]) VALUES (6102, '', 'Is there a contingency/business continuity plan with the provider for restoration?', '', '', '', 1, 3, 8, NULL, 2327, 0, '', NULL, NULL, 709)
